"""Apply the whole-server metrics beta to the published v1.1.3 checkout."""
import base64
import hashlib
import json
import re
import zlib
from pathlib import Path

PAYLOAD = """"""
root = Path.cwd()
bundle = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
manifest = root / "custom_components/scottibyte_incus/manifest.json"
if not manifest.exists():
    raise SystemExit("Run from your ha-scottibyte-incus checkout.")
version = json.loads(manifest.read_text())["version"]
if version not in ("1.1.3", "1.2.0-beta.1"):
    raise SystemExit(f"Expected 1.1.3 or 1.2.0-beta.1; found {version}. No files modified.")
for name, expected in bundle["expected"].items():
    path = root / name
    if not path.exists():
        if expected is None:
            continue
        raise SystemExit(f"Missing {name}; no files modified.")
    current = path.read_text().rstrip()
    if current == bundle["files"][name].rstrip():
        continue
    if expected is None or hashlib.sha256(current.encode()).hexdigest() != expected:
        raise SystemExit(f"Unexpected local changes in {name}; no files modified.")
readme = root / "README.md"
text = readme.read_text()
text = re.sub(r"\*\*Version [^\n]+", "**Version 1.2.0-beta.1 — whole-server metrics testing.** Live acceptance of the new host monitoring is pending. v1.1.3 remains the stable release; enable beta releases in HACS to select this candidate.", text, count=1)
text = text.replace("Select the numbered **v1.1.3** release in HACS.", "For testing, enable beta releases and select **v1.2.0-beta.1** in HACS; **v1.1.3** remains stable.")
text = text.replace("Ongoing requests use certificate authentication only.", "Incus requests use certificate authentication. Optional host monitoring uses a separate restricted SSH key; supplied setup passwords and SSH keys are discarded.")
text = text.replace("over HTTPS for normal use (default ports 22 and 8443).", "over HTTPS for Incus management (default ports 22 and 8443). Optional host monitoring also needs ongoing SSH access.")
text = text.replace("Server inventory polls every 30 seconds by default. Change it under the integration's options (10–300 seconds).", "Server inventory and host metrics poll every 30 seconds by default. The dashboard and integration options share a global 10/30/60/300-second setting.")
if "## Whole-server monitoring and refresh (v1.2 testing)" not in text:
    text += bundle["documentation"]
for name, content in bundle["files"].items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
readme.write_text(text)
print("Whole-server metrics and saved polling interval applied; version 1.2.0-beta.1.")
print("Existing servers: Reconfigure → Set up or disable whole-server metrics.")
